css:
.hero{position:relative; overflow:hidden; background:#f7f7f5}
.blob{position:absolute; border-radius:50%}
.blob.pink{left:-32%; top:6%; width:46%; aspect-ratio:1; background:#f4c3ca}
.blob.blue{top:-22%; right:22%; width:34%; aspect-ratio:1.4/1; background:#8fd3ec}
.blob.navy{right:-9%; top:40%; width:34vw; aspect-ratio:1; background:#1e3350; z-index:0}
/* タイル群を全方向で切る */
section{height:100svh; overflow:hidden; padding:0}
.tiles{width:calc(100% + 160px); margin-inline:-80px}
.cta{position:absolute; bottom:40px; left:50%; transform:translateX(-50%)}
